using NovaHarvest.Core.World;
namespace NovaHarvest.Core.Player; public sealed class PlayerInteraction { readonly PlayerController _player; public PlayerInteraction(PlayerController player) { _player = player; } public IReadOnlyList<WorldObject> GetInteractableObjects(WorldManager world, int radius = 1) => _player.GetNearbyObjects(world, radius).Where(x => x.IsInteractable).ToList(); public bool CanInteract(WorldObject o) => o.IsInteractable && Math.Abs(o.X - _player.Position.X) <= 1 && Math.Abs(o.Y - _player.Position.Y) <= 1; }
